package com.traceback.core.domain;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.FetchType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;
import jakarta.persistence.PrePersist;
import jakarta.persistence.PreUpdate;
import jakarta.persistence.Table;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

/**
 * Candidate root-cause hypothesis generated by Traceback for an incident.
 */
@Entity
@Table(name = "hypotheses")
public class Hypothesis {

    @Id
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "incident_id", nullable = false)
    private Incident incident;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "candidate_event_id", nullable = false)
    private Event candidateRootCause;

    @Column(name = "rank", nullable = false)
    private int rank;

    @Column(name = "confidence_score", nullable = false)
    private double confidenceScore;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false, length = 32)
    private HypothesisStatus status;

    @Column(name = "summary", nullable = false, columnDefinition = "text")
    private String summary;

    @Column(name = "verification_plan", columnDefinition = "text")
    private String verificationPlan;

    @Column(name = "counter_evidence", columnDefinition = "text")
    private String counterEvidence;

    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt;

    public Hypothesis() {
    }

    public Hypothesis(UUID id, Incident incident, Event candidateRootCause, int rank,
                      double confidenceScore, HypothesisStatus status, String summary,
                      String verificationPlan, String counterEvidence) {
        this.id = id != null ? id : UUID.randomUUID();
        this.incident = incident;
        this.candidateRootCause = candidateRootCause;
        this.rank = rank;
        this.confidenceScore = confidenceScore;
        this.status = status != null ? status : HypothesisStatus.PROPOSED;
        this.summary = summary;
        this.verificationPlan = verificationPlan;
        this.counterEvidence = counterEvidence;
    }

    @PrePersist
    protected void onCreate() {
        if (this.id == null) {
            this.id = UUID.randomUUID();
        }
        Instant now = Instant.now();
        if (this.createdAt == null) {
            this.createdAt = now;
        }
        if (this.updatedAt == null) {
            this.updatedAt = now;
        }
        if (this.status == null) {
            this.status = HypothesisStatus.PROPOSED;
        }
    }

    @PreUpdate
    protected void onUpdate() {
        this.updatedAt = Instant.now();
    }

    // Getters and Setters

    public UUID getId() {
        return id;
    }

    public void setId(UUID id) {
        this.id = id;
    }

    public Incident getIncident() {
        return incident;
    }

    public void setIncident(Incident incident) {
        this.incident = incident;
    }

    public Event getCandidateRootCause() {
        return candidateRootCause;
    }

    public void setCandidateRootCause(Event candidateRootCause) {
        this.candidateRootCause = candidateRootCause;
    }

    public int getRank() {
        return rank;
    }

    public void setRank(int rank) {
        this.rank = rank;
    }

    public double getConfidenceScore() {
        return confidenceScore;
    }

    public void setConfidenceScore(double confidenceScore) {
        this.confidenceScore = confidenceScore;
    }

    public HypothesisStatus getStatus() {
        return status;
    }

    public void setStatus(HypothesisStatus status) {
        this.status = status;
    }

    public String getSummary() {
        return summary;
    }

    public void setSummary(String summary) {
        this.summary = summary;
    }

    public String getVerificationPlan() {
        return verificationPlan;
    }

    public void setVerificationPlan(String verificationPlan) {
        this.verificationPlan = verificationPlan;
    }

    public String getCounterEvidence() {
        return counterEvidence;
    }

    public void setCounterEvidence(String counterEvidence) {
        this.counterEvidence = counterEvidence;
    }

    public Instant getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(Instant createdAt) {
        this.createdAt = createdAt;
    }

    public Instant getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(Instant updatedAt) {
        this.updatedAt = updatedAt;
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof Hypothesis that)) return false;
        return Objects.equals(id, that.id);
    }

    @Override
    public int hashCode() {
        return Objects.hash(id);
    }

    @Override
    public String toString() {
        return "Hypothesis{" +
                "id=" + id +
                ", rank=" + rank +
                ", confidenceScore=" + confidenceScore +
                ", status=" + status +
                ", summary='" + summary + '\'' +
                '}';
    }
}
